(() => {
 const H = window.Hou = {};
 H.e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={today:'<rect x="3" y="5" width="14" height="12" rx="2"/><path d="M6 3v4m8-4v4M3 9h14m-10 4h2"/>',library:'<path d="M3 4h5a3 3 0 0 1 3 3v10a4 4 0 0 0-3-1H3zm14 0h-3a3 3 0 0 0-3 3v10a4 4 0 0 1 3-1h3z"/>',record:'<path d="M5 3h8l3 3v11H5zM12 3v4h4M8 10h5m-5 3h5"/>',settings:'<path d="M4 5h12M4 10h12M4 15h12"/><circle cx="7" cy="5" r="2"/><circle cx="13" cy="10" r="2"/><circle cx="8" cy="15" r="2"/>',arrow:'<path d="M4 10h12m-5-5 5 5-5 5"/>',up:'<path d="M5 15 15 5M5 5h10v10"/>',back:'<path d="M16 10H4m5-5-5 5 5 5"/>',chevron:'<path d="m7 5 5 5-5 5"/>',plus:'<path d="M10 4v12M4 10h12"/>',clock:'<circle cx="10" cy="10" r="7"/><path d="M10 6v4l3 2"/>',bell:'<path d="M4 14h12l-2-3V8a4 4 0 0 0-8 0v3zm4 3h4"/>',sun:'<circle cx="10" cy="10" r="3"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M4 4l1 1m10 10 1 1M4 16l1-1M15 5l1-1"/>',moon:'<path d="M16 12a7 7 0 0 1-9-9 7 7 0 1 0 9 9Z"/>',close:'<path d="m5 5 10 10M5 15 15 5"/>',check:'<path d="m4 10 4 4 8-8"/>',doc:'<path d="M5 2h7l4 4v12H5zM12 2v5h4M8 11h5m-5 3h5"/>',upload:'<path d="M10 13V3M6 7l4-4 4 4M3 13v4h14v-4"/>',pause:'<path d="M7 4v12m6-12v12"/>',play:'<path d="m6 4 10 6-10 6z"/>',more:'<circle cx="4" cy="10" r=".7"/><circle cx="10" cy="10" r=".7"/><circle cx="16" cy="10" r=".7"/>',mark:'<path d="m4 13 8-9 4 4-8 9H4zm6-7 4 4M3 19h14"/>',note:'<path d="M4 3h12v11l-4 4H4zm7 15v-5h5M7 7h6M7 10h3"/>',info:'<circle cx="10" cy="10" r="7"/><path d="M10 9v5m0-8v1"/>',archive:'<path d="M3 3h14v4H3zm1 4v10h12V7M8 10h4"/>',repeat:'<path d="M16 7a6 6 0 0 0-10-3L3 7m0-4v4h4m-4 6a6 6 0 0 0 10 3l3-3m0 4v-4h-4"/>',key:'<circle cx="7" cy="8" r="4"/><path d="m10 11 6 6m-3-3 2-2m-4 0 2-2"/>'};
 H.icon=(name,extra='')=>`<svg class="od-icon icon ${extra}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.doc}</svg>`;
 const e=H.e, icon=H.icon;
 H.button=(label,action,cls='text-button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
 const b=H.button;
 H.book=id=>H.state.books.find(x=>x.id===id);
 H.pending=()=>H.state.tasks.filter(t=>t.status==='pending'&&!H.book(t.book)?.paused&&!H.book(t.book)?.archived);
 H.scheduled=()=>H.state.tasks.filter(t=>t.status==='scheduled'&&!H.book(t.book)?.paused&&!H.book(t.book)?.archived);
 H.source=t=>`${H.book(t.book).title} · ${H.book(t.book).sections[t.section].title}`;
 const attrs=id=>`data-id="${e(id)}"`;
 H.bars=n=>`<div class="mastery-bars" aria-label="掌握程度 ${n}，${HouData.levels[n-1]}">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'filled':''}"></i>`).join('')}</div>`;
 H.head=(eyebrow,title,description,action='')=>`<div class="page-head"><div class="od-field"><span class="eyebrow">${e(eyebrow)}</span><h1 tabindex="-1">${e(title)}</h1>${description?`<p>${e(description)}</p>`:''}</div>${action}</div>`;
 H.end=()=>`<footer class="page-end"><span class="od-row">${icon('info')}项目文档作为阅读示例 · 本地交互</span><span>理解，按自己的节奏生长。</span></footer>`;
 H.empty=(title,description,button='')=>`<div class="empty">${icon('library')}<h2>${e(title)}</h2><p>${e(description)}</p>${button}</div>`;
 H.row=t=>`<div class="pending-row"><span class="row-index">${String(H.pending().indexOf(t)+1).padStart(2,'0')}</span><div class="od-fill od-field"><button class="pending-title" type="button" data-action="start" ${attrs(t.id)}>${e(t.title)}</button><span class="pending-source">${e(H.source(t))}</span></div><span class="row-duration">约 ${t.minutes} 分钟</span>${b(icon('chevron'),'start','icon-button',`${attrs(t.id)} aria-label="开始考察：${e(t.title)}"`)}</div>`;
 H.today=()=>{
  const pending=H.pending(), first=pending[0], date=new Date(), day=date.getDate(), weekday=['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][date.getDay()];
  const upcoming=H.scheduled();
  return `<div class="main">${H.head(`${date.getMonth()+1} 月 ${day} 日 · ${weekday}`,'今天，读厚一点。','留几分钟，看看读过的内容理解了多少。',`<div class="calendar-stamp od-stat"><span class="day">${day}</span><span class="month">${String(date.getMonth()+1).padStart(2,'0')} / ${date.getFullYear()}</span></div>`)}
  <section aria-label="待完成的考察"><div class="section-heading"><h2>待完成的考察${pending.length?`<span class="number-tag">${pending.length}</span>`:''}</h2><span class="section-meta">不必一次做完</span></div>${first?`<article class="action-card"><span class="caption"><span class="status-dot"></span>现在可以做的一件事<span>·</span>约 ${first.minutes} 分钟</span><h2>把理解，放进一个新情境。</h2><p>${e(first.description)}</p><div class="source-line">${icon('library')}<span>${e(H.source(first))}</span></div><div class="action-footer">${b(`开始考察 ${icon('up')}`,'start','primary',attrs(first.id))}${b('稍后再做','delay','text-button',attrs(first.id))}<span class="action-index">${first.level} · ${String(1).padStart(2,'0')} / ${String(pending.length).padStart(2,'0')}</span></div></article>${pending.slice(1).map(H.row).join('')}`:H.empty('现在没有待完成的考察',upcoming.length?'下一次考察已安排好。也可以主动领取一项。':'读完一个章节，理解就有了下一次生长的起点。',b(upcoming.length?'主动领取':'去阅读',upcoming.length?'claim':'library','primary'))}</section>
  <section class="below"><div class="section-heading"><h2>接下来的安排</h2>${b('查看安排 '+icon('arrow'),'schedule','text-button')}</div>${upcoming.length?`<div class="schedule">${upcoming.slice(0,2).map(t=>`<div class="schedule-item"><div class="schedule-time od-row">${icon('clock')}${e(t.when)}</div><h3>${e(t.title)}</h3><div class="caption">${e(H.book(t.book).title)} · ${t.level} · ${t.minutes} 分钟</div>${b('为什么安排在这时？','reason','',attrs(t.id))}</div>`).join('')}</div>`:`<div class="notice">完成一次考察后，这里会出现接下来的安排。</div>`}</section>
  <section class="below"><div class="section-heading"><h2>理解正在生长</h2><span class="section-meta">按内容查看</span></div><div class="mastery-list">${H.state.books.filter(x=>!x.archived).slice(0,3).map(book=>{const tasks=H.state.tasks.filter(t=>t.book===book.id);const n=tasks.length?Math.round(tasks.reduce((s,t)=>s+t.mastery,0)/tasks.length):0;return `<div class="mastery-row"><div class="od-fill od-field">${b(e(book.title),'book-detail','pending-title',attrs(book.id))}<span class="caption">${tasks.length} 个知识点${book.paused?' · 考察已暂停':''}</span></div>${n?H.bars(n):''}<span class="mastery-level">${n?HouData.levels[n-1]:'待考察'}</span></div>`}).join('')}</div></section>${H.end()}</div>`;
 };
 H.library=()=>{
  const archived=H.state.filter==='archived',books=H.state.books.filter(x=>x.archived===archived);
  return `<div class="main">${H.head('阅读与理解','内容库','把值得理解的内容，留在这里。',b(icon('plus')+'导入内容','import','primary'))}<div class="library-toolbar"><div class="tabs" role="tablist" aria-label="内容状态">${['active','archived'].map((v,i)=>b(['阅读中','已归档'][i],'filter','',`data-value="${v}" role="tab" aria-selected="${H.state.filter===v}" tabindex="${H.state.filter===v?0:-1}"`)).join('')}</div><span class="caption">${books.length} 份内容</span></div>${books.length?books.map(book=>`<article class="library-row"><div class="document-symbol">${icon('doc')}</div><div class="od-fill"><h2>${b(e(book.title),'read','pending-title',attrs(book.id))}</h2><p>${e(book.description)}</p><div class="library-meta"><span>${book.type}</span><span>${book.sections.length} 个章节</span><span>${book.paused?'考察已暂停':archived?'已归档，保留历史':'阅读位置已记住'}</span></div></div><div class="row-actions">${b(icon(archived?'repeat':'more'),archived?'unarchive':'book-menu','icon-button',`${attrs(book.id)} aria-label="${archived?'恢复':'管理'}${e(book.title)}"`)}</div></article>`).join(''):H.empty(archived?'还没有归档的内容':'从一份内容开始',archived?'归档会停止相关考察，并保留历史记录。':'导入正文，读完之后再考察一次理解。',archived?'':b('导入内容','import','secondary'))}${H.end()}</div>`;
 };
 H.reader=()=>{
  const book=H.book(H.state.bookId),section=book.sections[book.chapter],key=`${book.id}:${book.chapter}`,done=H.state.completed.includes(key),marks=H.state.marks[key]||[],note=H.state.notes[key]||'';
  return `<div class="reader-wrap"><aside class="toc" aria-label="章节目录"><div class="toc-title">目录 · ${book.sections.length} 章</div>${book.sections.map((s,i)=>b(`<span class="muted">${String(i+1).padStart(2,'0')}</span><span>${e(s.title)}</span>`,'chapter','',`data-index="${i}" aria-current="${book.chapter===i}"`)).join('')}<div class="caption">${e(book.author)}<br>正文来自项目原始文档</div></aside><article class="reader-content"><div class="reader-meta">${e(book.title)} / 第 ${book.chapter+1} 章</div><h1 tabindex="-1">${e(section.title)}</h1>${H.state.sourceReturn?`<div class="source-banner od-row spaced"><span>正在查看本次考察的原文出处</span>${b('返回结果','return-result','inline-link')}</div>`:''}<div class="reader-text" id="reader-text">${section.text.map((p,i)=>`<p data-paragraph="${i}" class="${marks.includes(i)?'highlighted ':''}${H.state.sourceReturn&&i===0?'source-target':''}">${e(p)}</p>`).join('')}</div><div class="reader-tools">${b(icon('mark')+'高亮段落','highlight','secondary')}${b(icon('note')+(note?'查看批注':'添加批注'),'annotation','text-button')}<span class="caption od-row">选中一段原文后高亮</span></div>${note?`<div class="annotation"><div class="caption">你的批注</div><p>${e(note)}</p></div>`:''}<div class="reader-bottom"><span class="caption">${done?'本章节已加入计划':`第 ${book.chapter+1} / ${book.sections.length} 章 · 阅读位置自动保留`}</span>${b((done?'再次提取':'标记读完')+' '+icon('check'),'extract-start','primary')}</div></article></div>`;
 };
 H.extract=()=>{
  const x=H.state.extraction,book=H.book(x.book),section=book.sections[x.section];
  return `<div class="main">${H.head('阅读之后','留下值得理解的知识。',`${book.title} · ${section.title}`)}<div class="notice">${x.loading?'正在整理本地示例知识点。真实提取需要配置模型服务。':'以下为本地示例提取。可以移除不想考察的知识点，其余会保留。'}</div>${x.loading?`<div class="loading-state"><h2>正在整理知识点…</h2><div class="loading-line"></div><p class="muted">原文位置会与知识点一起保留。</p></div>`:`<div class="extraction-list">${x.points.map((p,i)=>`<article class="knowledge-card ${p.removed?'removed':''}"><div class="od-row spaced"><h3>${e(p.title)}</h3>${b(p.removed?'恢复':icon('close'),'toggle-point','icon-button',`data-index="${i}" aria-label="${p.removed?'恢复':'移除'}知识点：${e(p.title)}"`)}</div>${p.removed?`<p>已移除，不会加入考察。</p>`:`<p>${e(p.text)}</p><div class="caption">原文出处 · ${e(section.title)}</div>`}</article>`).join('')}</div><div class="form-actions">${b('返回阅读','reader','text-button')}${b(`保留 ${x.points.filter(p=>!p.removed).length} 个并加入计划`,'confirm-extraction','primary')}</div>`}</div>`;
 };
 H.game=()=>{
  const g=H.state.game,t=H.state.tasks.find(x=>x.id===g.taskId),question=g.questions[g.step];
  return `<div class="assessment-shell"><header class="assessment-top"><div class="od-field"><span class="serif">厚 / 考察</span><span class="caption">${e(t.title)} · 本地示例</span></div>${b(icon('close')+'稍后再做','exit-game','text-button')}</header>${g.phase==='loading'?`<div class="loading-state"><div class="eyebrow">为一次理解，准备一个情境</div><h1 tabindex="-1">正在准备考察…</h1><div class="loading-line"></div><p class="muted">正在载入本地示例，未向模型发送请求。</p><span class="caption">${e(H.source(t))}</span></div>`:g.phase==='error'?H.empty('暂时无法开始',g.error+' 本次不计入掌握程度。',b('重新准备','retry-game','primary')):`<div class="eyebrow">${g.readonly?'历史考察 · 只读':`第 ${g.step+1} / ${g.questions.length} 个情境`} · 识别与判断</div><h1 tabindex="-1">${e(question.question)}</h1><p class="assessment-intro">${g.readonly?'查看当时的选项与作答，不产生新的判断。':'选择你认为更合适的做法，再用自己的话解释。'}</p><div class="game-options" role="radiogroup" aria-label="你的选择">${question.choices.map((c,i)=>b(`<span class="choice-check">${g.answers[g.step]===i?icon('check'):String.fromCharCode(65+i)}</span><span>${e(c)}</span>`,'choose','game-choice',`data-index="${i}" role="radio" aria-checked="${g.answers[g.step]===i}" tabindex="${g.answers[g.step]===i||(g.answers[g.step]===undefined&&i===0)?0:-1}" ${g.readonly?'disabled':''}`)).join('')}</div><div class="form-field"><label for="explanation">你的判断理由${g.readonly?'':'（选填）'}</label><textarea id="explanation" placeholder="这个选择，怎样帮助用户理解内容？" ${g.readonly?'readonly':''}>${e(g.notes[g.step]||'')}</textarea><span class="caption">本地示例只核对所选选项；文字理由会保留，不作语义评分。</span></div><div class="step-track" aria-hidden="true">${g.questions.map((_,i)=>`<i class="${i<=g.step?'active':''}"></i>`).join('')}</div><div class="game-bottom"><span class="caption">${e(H.source(t))}</span>${g.step?b('上一个情境','game-prev','text-button'):''}${g.answers[g.step]===undefined&&!g.readonly?'<span class="caption choice-hint" id="choice-hint">先选择一个做法，才能继续</span>':''}${b(g.step===g.questions.length-1?(g.readonly?'返回记录':'提交作答'):'下一个情境','game-next','primary',g.answers[g.step]===undefined&&!g.readonly?'disabled aria-describedby="choice-hint"':'')}</div>`}</div>`;
 };
 H.result=()=>{
  const record=H.state.records.find(x=>x.id===H.state.recordId),t=H.state.tasks.find(x=>x.id===record.taskId),level=record.override||record.level,correct=record.answers.filter((a,i)=>a===record.questions[i].correct).length;
  return `<div class="assessment-shell"><header class="assessment-top"><span class="serif">厚 / 理解反馈</span>${b('返回今天 '+icon('close'),'today','text-button')}</header><div class="eyebrow">本次考察已完成 · 示例反馈</div><h1 tabindex="-1">理解，从这里再深一点。</h1><div class="result-card"><div class="result-label">${icon(correct===record.questions.length?'check':'info')}<span>${record.override?'采用你的结论':correct===record.questions.length?'部分掌握':correct?'部分掌握':'存在误解'}</span></div><h2>${e(t.title)}</h2><div class="od-row gap-16">${H.bars(level)}<span>${HouData.levels[level-1]}</span></div><p class="footnote">${record.override?'已保留原示例结论与复核记录，以你的结论更新计划。':`本地规则核对：${correct} / ${record.questions.length} 项选择符合原文。此示例仅检测识别，不推断解释、应用或迁移能力。`}</p></div>${record.questions.map((q,i)=>`<section class="result-details"><div class="od-row spaced"><h3>情境 ${i+1} · ${record.answers[i]===q.correct?'选择符合原文':'需要再想一想'}</h3>${icon(record.answers[i]===q.correct?'check':'info')}</div><p>${e(q.explanation)}</p><div class="answer-comparison"><div class="od-field"><span class="caption">你的选择</span><p>${e(q.choices[record.answers[i]])}</p></div><div class="od-field"><span class="caption">原文支持的选择</span><p>${e(q.choices[q.correct])}</p></div></div>${record.notes[i]?`<p class="footnote">你的理由：${e(record.notes[i])}</p>`:''}</section>`).join('')}<section class="result-details"><h3>回到原文</h3><p>${e(H.book(t.book).sections[t.section].text[0])}</p>${b(e(H.source(t))+' '+icon('up'),'source','inline-link',attrs(t.id))}</section><section class="result-details"><h3>接下来，再换一个角度。</h3><p>${e(record.next)} · 约 ${t.minutes} 分钟</p><p>示例安排：${level<=2?'先巩固当前概念，再逐步进入新情境。':'保留适当间隔，再从新的情境考察。'}真实安排由计划器结合历次记录决定。</p></section>${record.dispute?`<div class="notice">已记录异议：${e(record.dispute)}${record.reviewed?'<br>已查看一次示例复核；真实复核尚需连接模型。':''}</div>`:''}<div class="game-bottom">${b(record.override?'查看结论记录':'对结果有异议','dispute','text-button')}${b('回到今天 '+icon('arrow'),'today','primary')}</div><p class="footnote">本页为可操作的规则示例，不代表模型已运行。</p></div>`;
 };
 H.settings=()=>`<div class="main">${H.head('按你的节奏','设置','把工具调到适合自己的状态。')}<section class="settings-section"><div class="section-heading"><h2>模型服务</h2><span class="tag">未连接</span></div><div class="notice">原型不发送模型请求。可以填写配置体验表单；密钥仅保留在当前页面内存中，刷新后清除。</div><div class="form-field"><label for="model-url">服务地址</label><input id="model-url" type="url" value="${e(H.state.config.url)}" placeholder="https://your-provider.example/v1" autocomplete="off"></div><div class="form-cols"><div class="form-field"><label for="model-name">模型名称</label><input id="model-name" value="${e(H.state.config.model)}" placeholder="填写服务商提供的模型名" autocomplete="off"></div><div class="form-field"><label for="model-key">API 密钥</label><input id="model-key" type="password" placeholder="本次会话内暂存" autocomplete="new-password" value="${e(H.secret||'')}"></div></div><p id="config-error" class="field-error" role="alert" hidden></p><div class="form-actions">${b('保存配置','save-config','primary')}</div></section><section class="settings-section"><h2>阅读与外观</h2><div class="settings-row"><div class="od-field"><span>外观</span><span class="caption">按当前页面选择浅色或深色</span></div><div class="tabs" role="tablist" aria-label="外观">${['light','dark'].map((v,i)=>b(['浅色','深色'][i],'theme','',`data-value="${v}" role="tab" aria-selected="${H.state.theme===v}" tabindex="${H.state.theme===v?0:-1}"`)).join('')}</div></div><div class="settings-row"><div class="od-field"><span>减少动态效果</span><span class="caption">仅保留状态变化，不使用位移动效</span></div>${b('<span></span>','reduce-motion','switch',`role="switch" aria-label="减少动态效果" aria-checked="${H.state.reduceMotion}"`)}</div></section><section class="settings-section"><h2>考察送达</h2><div class="settings-row"><div class="od-field"><span>主动领取快捷键</span><span class="caption">原型中仅在本页面生效</span></div>${b(e(H.state.config.shortcut),'shortcut','secondary')}</div><div class="settings-row"><div class="od-field"><span>固定考察时段</span><span class="caption">原型仅保存设置，不触发系统窗口</span></div>${b('<span></span>','toggle-schedule','switch',`role="switch" aria-label="固定考察时段" aria-checked="${H.state.config.scheduled}"`)}</div>${H.state.config.scheduled?`<div class="form-field"><label for="schedule-time">每天的时间</label><input id="schedule-time" type="time" value="${e(H.state.config.time)}"></div>`:''}<div class="settings-row"><div class="od-field"><span>菜单栏与通知</span><span class="caption">在页面内查看待完成面板和通知样式</span></div>${b('查看通知','notification','secondary')}</div></section>${H.end()}</div>`;
 H.records=()=>`<div class="main">${H.head('每一步，都有来处','运行记录','保留触发、作答、判断与接下来的安排。')}${H.state.records.length?H.state.records.slice().reverse().map(r=>{const t=H.state.tasks.find(x=>x.id===r.taskId);return `<article class="log-row"><div class="log-date od-field"><span>${e(r.date)}</span><span>${e(r.time)}</span></div><div class="od-fill"><h3>${b(e(t.title),'log','pending-title',attrs(r.id))}</h3><p>${e(r.status==='interrupted'?'考察中断 · 未计入掌握程度':`考察完成 · ${HouData.levels[(r.override||r.level)-1]}`)}</p><span class="caption">${e(r.trigger)} · 本地示例</span></div><div class="row-actions">${b(icon('chevron'),'log','icon-button',`${attrs(r.id)} aria-label="查看运行记录"`)}</div></article>`}).join(''):H.empty('还没有运行记录','完成一次考察后，触发原因与作答会一起留在这里。',b('回到今天','today','secondary'))}${H.end()}</div>`;
 H.log=()=>{
  const r=H.state.records.find(x=>x.id===H.state.recordId),t=H.state.tasks.find(x=>x.id===r.taskId);
  return `<div class="main">${H.head('运行记录 · 本地示例',t.title,`${r.date} ${r.time} · ${r.trigger}`)}<div class="notice">${r.status==='interrupted'?'考察中途关闭，已回到待完成列表。本次不计入掌握程度。':'本次使用本地预设情境与规则。未调用 LLM，未产生模型输入、输出或组件版本记录。'}</div>${[{label:'知识点与原文',value:{title:t.title,source:H.source(t),passage:H.book(t.book).sections[t.section].text[0]}},{label:'操作过程与作答',value:{operations:r.operations,answers:r.answers,notes:r.notes,status:r.status}},{label:'判断与计划',value:{level:r.level?HouData.levels[r.level-1]:'未判断',userConclusion:r.override?HouData.levels[r.override-1]:null,dispute:r.dispute||null,reviewed:r.reviewed||false,next:r.next||null}}].map(x=>`<details open><summary>${e(x.label)}</summary><pre>${e(JSON.stringify(x.value,null,2))}</pre></details>`).join('')}<div class="form-actions">${b('返回列表','records','text-button')}${r.status==='complete'?b('查看当时的考察','replay','secondary',attrs(r.id)):''}${r.status==='complete'?b('查看结果','record-result','primary',attrs(r.id)):''}</div></div>`;
 };
 H.schedule=()=>`<div class="main">${H.head('理解需要一点间隔','接下来的安排','时间可以调整，节奏由你决定。')}${H.scheduled().length?H.scheduled().map(t=>`<article class="pending-row"><div class="od-fill od-field"><span class="caption">${e(t.when)}</span><h2>${e(t.title)}</h2><span class="caption">${e(H.source(t))}</span><p class="muted">${e(t.reason)}</p></div>${b('延后','delay','secondary',attrs(t.id))}</article>`).join(''):H.empty('暂无接下来的安排','完成一次考察，或读完一个章节后，会出现新的安排。')}${H.end()}</div>`;
 H.bookDetail=()=>{
  const book=H.book(H.state.bookId),tasks=H.state.tasks.filter(t=>t.book===book.id);
  return `<div class="main">${H.head('按章节理解',book.title,book.description,b('继续阅读 '+icon('arrow'),'read','primary',attrs(book.id)))}<div class="settings-row"><div class="od-field"><span>这份内容的考察</span><span class="caption">${book.paused?'已暂停，阅读与历史记录不受影响':'按计划进行，可以随时暂停'}</span></div>${b(book.paused?'恢复考察':'暂停考察','pause-book','secondary',attrs(book.id))}</div>${tasks.length?tasks.map(t=>`<article class="pending-row"><div class="od-fill od-field"><h3>${e(t.title)}</h3><span class="caption">${e(book.sections[t.section].title)}</span><span class="caption">${t.status==='pending'?'待完成':e(t.when||'已安排')}</span></div>${H.bars(t.mastery)}<span class="mastery-level">${HouData.levels[t.mastery-1]}</span></article>`).join(''):H.empty('还没有知识点','读完一个章节，再把值得理解的知识加入计划。')}${H.end()}</div>`;
 };
})();
